void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec2 z = iMouse.xy/iResolution.xy * 2.0 - 1.0;

    if (iMouse.xy == vec2(0))
    {
        z = vec2(0.5 * iResolution.y / iResolution.x, sin(iTime));
    }

    z.x *= iResolution.x / iResolution.y;
    z.x -= 0.5;
    vec2 f = vec2(uv.x * uv.x - uv.y * uv.y + z.x, 2.0 * uv.x * uv.y + z.y);
    vec3 col = vec3(0,0,0);
    float a = 0.0;
    float num = 0.0;

    for(int i = 0; i < 1000; i++)
    {
        f = vec2(f.x * f.x - f.y * f.y + z.x, 2.0 * f.x * f.y + z.y);

        a = pow(f.x * f.x + f.y * f.y - 4.0, -1.0);

        if(a <= 0.0)
        {
            col = vec3(num*0.1,num*0.1,num*0.1);
        }

        num += 0.5;
    }

    a = f.x * f.x + f.y * f.y;

    if(a <= 0.0)
    {
        col = vec3(1.0,1.0,1.0);
    }


    // Output to screen
    fragColor = vec4(col,1.0);
}
